args.command:
cd /opt/ce-work/shell/stuck-requests/ws && for r in $(cat out/stuck.txt); do
  e=$(grep -l " ERROR .* $r" logs/app-*.log | tr '\n' ' ');
  d=$(grep -l " done .* $r" logs/app-*.log | tr '\n' ' ');
  s=$(grep -l " start .* $r" logs/app-*.log | tr '\n' ' ');
  echo "$r ERR[$e] DONE[$d] START[$s]"
done
echo ===; grep -E "done .*(req-0019|req-0333|req-0372)" logs/app-*.log
echo ===; cat out/stuck.txt
echo ===; sort -c out/stuck.txt && echo SORTED; wc -l out/stuck.txt; tail -c 20 out/stuck.txt | xxd | tail -2
